 [q('Ethiopia lies between longitudes…','ኢትዮጵያ የምትገኘው በ… ኬንትሮስ መካከል ነው',['33°E – 48°E','3°E – 15°E','48°W – 33°W']),q('How many neighbouring countries does Ethiopia have?','ኢትዮጵያ ስንት ጎረቤት አገሮች አሏት?',['6','4','9']),
  q('Djibouti is to the … of Ethiopia.','ጅቡቲ ከኢትዮጵያ በ… ትገኛለች።',[('north-east','ሰሜን ምሥራቅ'),('south-west','ደቡብ ምዕራብ'),('south','ደቡብ')]),q('Location described by latitude and longitude is…','በኬክሮስና በኬንትሮስ የሚገለጽ መገኛ…',[('absolute location','ፍጹማዊ መገኛ'),('relative location','አንጻራዊ መገኛ'),('sketch','ንድፍ')])],
 notes(('We can describe where Ethiopia is by directions, neighbours (relative) and latitude–longitude (absolute).','ኢትዮጵያ የት እንዳለች በአቅጣጫ፣ በጎረቤቶች (አንጻራዊ) እና በኬክሮስ–ኬንትሮስ (ፍጹማዊ) መግለጽ እንችላለን።'),
  [('4 main directions + 4 sub-directions.','4 ዋና + 4 ንዑስ አቅጣጫዎች።'),('Neighbours: Eritrea, Djibouti, Somalia, Kenya, South Sudan, Sudan.','ጎረቤቶች፦ ኤርትራ፣ ጅቡቲ፣ ሶማሊያ፣ ኬንያ፣ ደቡብ ሱዳን፣ ሱዳን።'),('Absolute: 3°N–15°N and 33°E–48°E.','ፍጹማዊ፦ 3°–15° ሰሜን፣ 33°–48° ምሥራቅ።'),('Grid, sketch maps, GPS and Google Earth help find places.','ፍርግርግ፣ ንድፍ ካርታ፣ ጂፒኤስና ጎግል መሬት ቦታ ለማግኘት ይረዳሉ።')],
  [('ኬክሮስ','latitude','ከምድር ወገብ ሰሜን/ደቡብ ርቀት'),('ኬንትሮስ','longitude','ከመነሻ ኬንትሮስ ምሥራቅ/ምዕራብ ርቀት'),('አንጻራዊ መገኛ','relative location','ከሌሎች ቦታዎች አንጻር'),('ጂፒኤስ','GPS','በሳተላይት ቦታ ማግኛ')],('Never Eat Soggy Waffles: N, E, S, W clockwise.','N፣ E፣ S፣ W በሰዓት አቅጣጫ።'),
  [(('Name the neighbour to the west','በምዕራብ ያለውን ጎረቤት ሰይሙ'),('Sudan / South Sudan','ሱዳን / ደቡብ ሱዳን')),(('What does GPS stand for?','GPS ምን ማለት ነው?'),'Global Positioning System')],
  (('Tour guide map','የአስጎብኚ ካርታ'),('Tour guides help visitors find places. Draw a sketch map from your school to a famous place nearby with directions.','አስጎብኚዎች ጎብኚዎች ቦታዎችን እንዲያገኙ ይረዳሉ። ከትምህርት ቤታችሁ በአቅራቢያ ወዳለ ታዋቂ ቦታ አቅጣጫ ያለው ንድፍ ካርታ ሳሉ።'),
   [('Mark north with an arrow.','ሰሜንን በቀስት ምልክት አድርጉ።'),('Draw roads, rivers and landmarks.','መንገዶችን፣ ወንዞችንና ምልክቶችን ሳሉ።'),('Write directions using NE, SW, etc.','ሰሜን ምሥራቅ፣ ደቡብ ምዕራብ… በመጠቀም አቅጣጫ ጻፉ።'),('If you can, check it on Google Maps.','ከቻላችሁ በጎግል ካርታ አረጋግጡ።')])),
