  [('Zones: Bereha, Kolla, Weyna Dega, Dega, Wurch.','ክልሎች፦ በረሃ፣ ቆላ፣ ወይና ደጋ፣ ደጋ፣ ውርጭ።'),('Higher = colder and usually wetter.','ከፍ ሲል = ይቀዘቅዛል፣ ብዙ ጊዜ ዝናብ ይጨምራል።'),('Seasons: Kiremt, Bega, Belg.','ወቅቶች፦ ክረምት፣ በጋ፣ በልግ።'),('Resources: renewable and non-renewable; use them wisely.','ሀብቶች፦ ታዳሽና የማይታደሱ፤ በአግባቡ ተጠቀሙባቸው።')],
